    font-size: 16px;
    font-weight: 500;
    color: var(--text-primary);
    margin-bottom: 16px;
    padding: 0;
    display: block;
    width: 100%;
}

.radio-group {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.radio-option {
    display: flex;
    align-items: center;
}

input[type="radio"] {
    position: absolute;
    opacity: 0;
    cursor: pointer;
}

