input[type="radio"]:checked + label .radio-custom {
    border-color: var(--primary-color);
    background-color: var(--primary-color);
    box-shadow: inset 0 0 0 3px var(--background);
}

input[type="radio"]:hover + label .radio-custom {
    border-color: var(--primary-color);
